function vanKey(bay,showEnds){
  const b=bayBounds(bay); if(!b)return "";
  const W=S.walls[b.side]||{cols:144,rows:60};
  return `<div class="vankey">
    <div class="vanwrap${b.side==="Driver side"?" mirrored":""}">
      <div class="vanbody">${vanSVG()}
        <div class="cargo" style="grid-template-columns:repeat(${W.cols},minmax(0,1fr));
          grid-template-rows:repeat(${W.rows},minmax(0,1fr));gap:0">
          <div class="here" style="grid-column:${b.x+1}/span ${b.w};grid-row:${b.y+1}/span ${b.h}"></div>
        </div></div></div>
    ${showEnds?`<div class="keyends"><span>${b.side==="Driver side"?"Rear":"Front"}</span><span>${b.side==="Driver side"?"Front":"Rear"}</span></div>`:""}
  </div>`;
}
